class MeshTest(unittest.TestCase):
    def test_adaptive_mesh(self):
        text = "\n".join(plr.mesh_section({"bed_mesh": ADAPTIVE_MESH}))
        cfg = configparser.ConfigParser()
        cfg.read_string(text)
        prof = cfg["bed_mesh plr"]
        # The mesh Klipper had in memory, loaded without interpolation
        points = [[float(v) for v in line.split(",")]
                  for line in prof["points"].strip().splitlines()]
        self.assertEqual(points, ADAPTIVE_MESH["mesh_matrix"])
        self.assertEqual((prof["x_count"], prof["y_count"], prof["mesh_x_pps"],
                          prof["mesh_y_pps"], prof["algo"]), ("11", "11", "0", "0", "direct"))
        self.assertEqual((prof["min_x"], prof["max_x"], prof["min_y"], prof["max_y"]),
                         ("205.0", "225.0", "205.0", "225.0"))

    def test_no_mesh(self):
        self.assertEqual(plr.mesh_section({"bed_mesh": {"profile_name": ""}}), [])
        with self.assertRaises(plr.PlanError):
            plr.mesh_section({"bed_mesh": {"profile_name": "x", "mesh_matrix": [[]]}})


class CheckpointTest(unittest.TestCase):
    def test_turned_off(self):
        with tempfile.TemporaryDirectory() as d:
            os.makedirs(os.path.join(d, "plr"))
            open(os.path.join(d, "plr", "disabled"), "w").close()
            # Returns before connecting to Klipper, which isn't there
            self.assertEqual(plr.main(["--data-dir", d, "checkpoint"]), 0)
            self.assertFalse(os.path.exists(os.path.join(d, "plr", "checkpoint.json")))
            os.remove(os.path.join(d, "plr", "disabled"))
            self.assertEqual(plr.main(["--data-dir", d, "checkpoint"]), 1)


class RealFileTest(unittest.TestCase):
    """Simulated power cuts at random places in a real file."""

    @unittest.skipUnless(os.environ.get("PLR_TEST_GCODE"), "PLR_TEST_GCODE not set")
    def test_random_cuts(self):
        path = os.environ["PLR_TEST_GCODE"]
        offsets = [o for o, _ in plr.iter_lines(path)]
        rng = random.Random(4)
        for _ in range(int(os.environ.get("PLR_TEST_CUTS", "10"))):
            fp = rng.choice(offsets[len(offsets) // 50:-200])
            back = rng.randint(0, 300)
            t = rng.choice([0.0, 0.5, rng.random()])
            cp, m = make_checkpoint(path, fp, -1 - back, t)
            p = plr.plan(cp, path)
            self.assertEqual(p["resume_offset"], m.offset, (fp, back, t))
            # The faster second pass must give the same state as reading from
            # the start of the file
            full = plr.GcodeModel(0.8, 0.0, window=1)
            for offset, text in plr.iter_lines(path, stop=p["resume_offset"]):
                full.feed(text, offset)
            s = p["state"]
            self.assertAlmostEqual(s.e, full.e, places=6)
            for attr in ("pos", "f", "abs_e", "fw_retracted", "slicer_retract", "layer",
                         "obj", "state_lines", "velocity", "defines", "line"):
                self.assertEqual(getattr(s, attr), getattr(full, attr), attr)


